import re
m2=open('reports/usage/m2.md').read()
def ids(label):
    m=re.search(label+r"[^:]*:\s*((?:`?[0-9a-f]{8}-[0-9a-f-]{27}`?\s*)+)",m2)
    return set(re.findall(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}",m.group(1)))
W=ids(r"workers \(9\)"); V=ids(r"validators \(22[^)]*\)")
print(len(W),len(V))
rows=[]
for l in open('/tmp/usage-m2.md'):
    if l.startswith('| `'):
        c=[x.strip() for x in l.strip().strip('|').split('|')]
        if len(c)==16: rows.append(c)
def tot(S):
    t=[0,0,0,0]
    for c in rows:
        if c[0].strip('`') in S:
            t[0]+=int(c[5]);t[1]+=int(c[6]);t[2]+=int(c[7]);t[3]+=int(c[8])
    return t
print('workers m2 list from mine', tot(W)); print('validators m2 list from mine', tot(V))
mineW={c[0].strip('`') for c in rows if c[1]=='worker'}; mineV={c[0].strip('`') for c in rows if c[1]=='validator'}
for name,m,l in (('worker',mineW,W),('validator',mineV,V)):
    print(name,'mine-not-listed:')
    for c in rows:
        if c[0].strip('`') in m-l: print('  ',c[0][1:9],c[1],c[2],c[3],c[4],'turns',c[5],'in',c[6],c[9],c[13],c[14])
    print(name,'listed-not-mine',l-m)
